import {BRIDGES,SPLITS,bridge,moveBridge,split,moveSplit,exchange,fromNumber,value} from './model.js';
const $=s=>document.querySelector(s),workspace=$('#workspace');
let mode='bridge',bridgeIndex=0,splitIndex=0,bs=bridge(),ss=split();
let selected=[],history=[],message='',hint=false,freeView='split',freeN=8,cut=5,bank=fromNumber(24),completed={bridge:new Set(),split:new Set()};
let memory=false,drag=null,suppressClick=false;
const words=['Null','Eins','Zwei','Drei','Vier','Fünf','Sechs','Sieben','Acht','Neun','Zehn'];
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function announce(text){$('#announcer').textContent=text;}
function remember(){history.push({bs:structuredClone(bs),ss:structuredClone(ss),bank:{...bank},freeN,cut,memory});if(history.length>30)history.shift();}
function reset(){if(mode==='bridge')bs=bridge(...BRIDGES[bridgeIndex]);if(mode==='split')ss=split(...SPLITS[splitIndex]);selected=[];history=[];message='';hint=false;memory=false;render();}
function setMode(next){if(!['bridge','split','free'].includes(next))throw new Error('Unbekannte Werkstatt');mode=next;selected=[];history=[];message='';hint=false;memory=false;window.speechSynthesis?.cancel();render();}
function dots(count,{kind='source',moved=[],selectable=false,orange=true}={}){return Array.from({length:count},(_,id)=>`<div class="slot filled">${moved.includes(id)?`<span class="bead ghost" aria-label="Stein ${id+1} wurde verschoben"></span>`:`<${selectable?'button':'span'} class="bead ${orange?'orange':''} ${selectable&&selected.includes(id)?'selected':''}" ${selectable?`data-select="${id}" data-kind="${kind}" aria-pressed="${selected.includes(id)}" aria-label="Stein ${id+1} aus der ${mode==='bridge'?bs.b:ss.n} auswählen"`:''}></${selectable?'button':'span'}>`}</div>`).join('');}
function targetFrame(){return Array.from({length:10},(_,i)=>{const base=i<bs.a,added=i>=bs.a&&i<bs.a+bs.moved.length;return `<${base||added?'div':'button'} class="slot ${base||added?'filled':''} ${hint&&!base&&!added?'hinted':''}" ${!base&&!added?'data-action="transfer" aria-label="Ausgewählte Steine in die freien Plätze legen"':''}>${base||added?`<span class="bead ${added?'orange':''}"></span>`:''}</${base||added?'div':'button'}>`;}).join('');}
function steps(phase){const rank={place:0,rest:1,total:2,done:3}[phase];return `<div class="steps" aria-label="Lernschritte">${['Zehn vollmachen','Rest entdecken','Zusammen sehen'].map((s,i)=>`<span class="step ${rank===i?'current':rank>i?'done':''}" ${rank===i?'aria-current="step"':''}><i>${rank>i?'✓':i+1}</i>${s}</span>`).join('')}</div>`;}
function answers(correct,type,max=20){const options=[correct+1,correct-1,correct,correct+2].filter(n=>n>=0&&n<=max),shift=(correct+bridgeIndex+splitIndex)%options.length,arr=[...options.slice(shift),...options.slice(0,shift)];return `<div class="answer-row" role="group" aria-label="Antwort auswählen">${[...new Set(arr)].map(n=>`<button class="answer" data-answer="${n}" data-answer-type="${type}" aria-label="${n}">${n}</button>`).join('')}</div>`;}
function controls(done=false){return `<div class="actions"><div class="action-left"><button class="secondary" data-action="undo" ${history.length?'':'disabled'}>↶ Zurück</button><button class="secondary" data-action="reset">Nochmal</button><button class="secondary" data-action="hint">Tipp</button></div>${done?'<button class="primary" data-action="next">Nächste Entdeckung</button>':''}</div>`;}
function bridgeInstruction(){if(message)return message;if(memory)return 'Wie viel ist das zusammen? Du kannst die Steine jederzeit aufdecken.';if(bs.phase==='place'){const need=10-bs.a-bs.moved.length;return selected.length?`${selected.length===1?'Ein Stein ist':selected.length+' Steine sind'} ausgewählt. Tippe jetzt auf einen freien Platz.`:`Fülle ${need===1?'den letzten freien Platz':'die '+need+' freien Plätze'}.`;}if(bs.phase==='rest')return `Wie viele von den ${bs.b} orangen Steinen sind noch drüben?`;if(bs.phase==='total')return `Zehn und ${bs.b-bs.moved.length}: Wie viel ist das zusammen?`;return `Du hast die ${words[bs.b]} geteilt und eine volle Zehn gebaut.`;}
function renderBridge(){const {a,b,moved,phase}=bs,rest=b-moved.length,done=phase==='done';return `<section class="card" aria-label="Zehnerbrücke"><div class="exercise-top"><div><div class="exercise-label">DEINE AUFGABE ${bridgeIndex+1}</div><div class="equation"><span class="blue-text">${a}</span><span>+</span><span class="orange-text">${b}</span><span>=</span><span class="${done?'':'question-box'}">${done?a+b:'?'}</span></div></div><span class="badge">${completed.bridge.size?completed.bridge.size+' entdeckt':'In deinem Tempo'}</span></div>${steps(phase)}${memory?`<div class="memory-cover"><span aria-hidden="true">✧</span><h2>Stell dir die Steine vor.</h2><p>Von der ${b} gehen ${10-a} zur ${a}.</p><p>Erst zur Zehn. Dann den Rest dazu.</p><button class="secondary" data-action="reveal">Steine aufdecken</button></div>`:`<div class="play-area"><div class="mat ${selected.length?'drop-ready':''}" data-drop="bridge"><div class="mat-title">${moved.length?phase==='place'?'Die Zehn wächst':'Eine volle Zehn':'Hier liegt die '+words[a]}<span class="amount blue-text">${a+moved.length}</span></div><div class="tenframe" role="group" aria-label="Zehnerfeld mit ${a} blauen und ${moved.length} orangen Steinen">${targetFrame()}</div><p class="frame-caption">${moved.length?`${a} blaue + ${moved.length} orange Steine`:`${10-a} ${10-a===1?'Platz ist':'Plätze sind'} noch frei.`}</p>${moved.length?`<div class="group-equation"><span class="blue-text">${a}</span> + <span class="orange-text">${moved.length}</span> = ${a+moved.length}</div>`:''}</div><div class="mat source"><div class="mat-title">Die ${words[b]} bleibt erkennbar<span class="amount orange-text">${b}</span></div><div class="tenframe" role="group" aria-label="Ursprüngliche Gruppe von ${b} Steinen, davon ${moved.length} verschoben">${dots(b,{moved,selectable:phase==='place'})}</div><p class="frame-caption">${moved.length?`${moved.length} ${moved.length===1?'Stein ist':'Steine sind'} zur ${words[a]} gewandert.<br>Die leeren Kreise zeigen, woher.`:'Wähle Steine aus dieser Gruppe.'}</p>${moved.length?`<div class="group-equation"><span>${b}</span> = <span class="chip">${moved.length}</span> + <span class="chip">${phase==='place'||phase==='rest'?'?':rest}</span></div>`:''}</div></div>`}${done?`<div class="success-panel" role="status"><h2>Du hast die Brücke gebaut!</h2><div class="sum-line">${a} + ${b} = 10 + ${rest} = ${a+b}</div><p>Von der ${b} hast du ${moved.length} genommen.<br>${rest} bleiben übrig. Alles zusammen ist ${a+b}.</p></div>`:`<div class="instruction"><span class="instruction-icon">${memory?'✧':phase==='place'?1:phase==='rest'?2:3}</span><div><span id="task-instruction">${esc(bridgeInstruction())}</span>${phase==='place'&&!memory?'<small>Steine antippen, dann einen freien Platz. Oder hinüberziehen.</small>':''}${memory?answers(a+b,'mental'):phase==='rest'?answers(rest,'rest',10):phase==='total'?answers(a+b,'total'):''}</div></div>`}${controls(done)}</section><div class="hint-bar"><span class="symbol" aria-hidden="true">✧</span><p>${phase==='place'?`<strong>Die fehlenden ${10-a} kommen aus der ${b}.</strong><br>Was du verschiebst, fehlt dort. Der Rest bleibt sichtbar.`:phase==='rest'?'<strong>Eine Zahl, zwei Teile.</strong><br>Ein Teil ist zur Zehn gewandert. Der andere Teil wartet noch.':'<strong>Die Anzahl bleibt gleich.</strong><br>Du hast die Steine nur anders angeordnet.'}</p></div>${completed.bridge.size>=2&&phase==='place'&&!moved.length&&!memory?'<button class="quiet mental-button" data-action="mental">Erst im Kopf versuchen</button>':''}`;}
function splitInstruction(){if(message)return message;if(ss.phase==='place')return `Lege ${ss.take} von den ${ss.n} Steinen auf die rechte Matte.`;if(ss.phase==='rest')return `Wie viele bleiben auf der linken Matte?`;return `Aus ${ss.n} werden ${ss.n-ss.take} und ${ss.take}. Zusammen sind es wieder ${ss.n}.`;}
function renderSplit(){const {n,take,moved,phase}=ss;return `<section class="card"><div class="exercise-top"><div><div class="exercise-label">DEINE AUFGABE ${splitIndex+1}</div><div class="equation"><span class="orange-text">${n}</span> = <span class="question-box">${phase==='done'?n-take:'?'}</span> + ${take}</div></div><span class="badge">${completed.split.size?completed.split.size+' entdeckt':'In deinem Tempo'}</span></div><div class="split-area"><div class="split-mats"><div class="mat source"><div class="mat-title">Hier waren ${n} Steine</div><div class="tenframe" role="group" aria-label="Ausgangsgruppe mit ${n} Steinen">${dots(n,{moved,selectable:phase==='place',kind:'split'})}</div><p class="frame-caption">Die leeren Plätze bleiben sichtbar.</p></div><div class="mat ${selected.length?'drop-ready':''}" data-drop="split"><div class="mat-title">Hierhin kommen ${take}<span class="amount orange-text">${moved.length}</span></div><div class="tenframe">${Array.from({length:take},(_,i)=>`<${i<moved.length?'div':'button'} class="slot ${i<moved.length?'filled':''}" ${i>=moved.length?'data-action="transfer" aria-label="Ausgewählte Steine auf die rechte Matte legen"':''}>${i<moved.length?'<span class="bead orange"></span>':''}</${i<moved.length?'div':'button'}>`).join('')}</div><p class="frame-caption">${take-moved.length?`Noch ${take-moved.length} ${take-moved.length===1?'Stein':'Steine'} passen hierhin.`:'Dieser Teil ist vollständig.'}</p></div></div></div>${phase==='done'?`<div class="success-panel" role="status"><h2>Beide Teile gehören zusammen.</h2><div class="sum-line">${n} = ${n-take} + ${take}</div><p>Links bleiben ${n-take}. Rechts liegen ${take}.<br>Zusammen sind es immer noch ${n}.</p><button class="secondary" data-action="reunite">Wieder zusammenschieben</button></div>`:`<div class="instruction"><span class="instruction-icon">${phase==='place'?1:2}</span><div><span id="task-instruction">${esc(splitInstruction())}</span>${phase==='place'?'<small>Wähle Steine und tippe auf die rechte Matte.</small>':answers(n-take,'split-rest',10)}</div></div>`}${controls(phase==='done')}</section><div class="hint-bar"><span class="symbol">✧</span><p><strong>Du kannst die Steine verschieben.</strong><br>Es werden dabei weder mehr noch weniger.</p></div>`;}
function freeDots(){return Array.from({length:freeN},(_,i)=>`<span class="free-dot bead ${i<cut?'':'orange'} ${i%5===4?'end-five':''}"></span>`).join('');}
function renderFreeSplit(){return `<div class="free-board"><div class="field-line"><span>Deine Zahl</span><div class="counter"><button data-action="number-down" aria-label="Zahl verkleinern" ${freeN===1?'disabled':''}>−</button><output aria-live="polite">${freeN}</output><button data-action="number-up" aria-label="Zahl vergrößern" ${freeN===20?'disabled':''}>+</button></div><span class="mini-label">1 bis 20</span></div><div class="free-split-display" role="img" aria-label="${freeN} Steine: ${cut} blau und ${freeN-cut} orange">${freeDots()}</div><div class="field-line split-controls"><label for="cut">Verschiebe die Grenze zwischen den beiden Teilen.</label><input id="cut" type="range" min="0" max="${freeN}" value="${cut}" aria-valuetext="${cut} und ${freeN-cut}"></div><div class="split-summary" aria-live="polite">${freeN} = <span class="blue-text">${cut}</span> + <span class="orange-text">${freeN-cut}</span></div><div class="button-row"><button class="secondary" data-action="swap-parts">Teile tauschen</button><button class="secondary" data-action="join-parts">Alles zusammen</button></div></div><div class="instruction"><span class="instruction-icon">✧</span><div>${esc(message||'Wie viele verschiedene Zerlegungen findest du?')}<small>Die Zahl bleibt gleich. Nur ihre beiden Teile ändern sich.</small></div></div>`;}
function renderBank(){return `<div class="free-board"><div class="field-line"><label for="build-number">Welche Zahl möchtest du bauen?</label><input id="build-number" type="number" min="0" max="100" step="1" value="${value(bank)}" inputmode="numeric"><button class="secondary" data-action="build">Bauen</button><span class="mini-label">0 bis 100</span></div><div class="free-piles"><div class="mat"><div class="mat-title">Zehner <span class="amount">${bank.tens}</span></div><div class="rods">${bank.tens?Array.from({length:bank.tens},(_,i)=>`<button class="rod" data-action="open-ten" aria-label="Zehner ${i+1} in zehn Einer öffnen" title="In 10 Einer öffnen"></button>`).join(''):'<p class="empty-message">Hier liegen noch keine Zehner.</p>'}</div></div><div class="mat source"><div class="mat-title">Einer <span class="amount">${bank.units}</span></div><div class="units-grid">${bank.units?Array.from({length:bank.units},()=>'<span class="unit"></span>').join(''):'<p class="empty-message">Keine einzelnen Steine.</p>'}</div></div></div><div class="free-result" aria-live="polite">${value(bank)} = ${bank.tens*10} + ${bank.units}</div><div class="button-row"><button class="primary" data-action="bundle-ten" ${bank.units>=10?'':'disabled'}>10 Einer bündeln</button><button class="secondary" data-action="open-ten" ${bank.tens?'':'disabled'}>1 Zehner öffnen</button><button class="secondary" data-action="undo" ${history.length?'':'disabled'}>↶ Zurück</button></div></div><div class="instruction"><span class="instruction-icon">=</span><div>${esc(message||'Ein Zehner ist genauso viel wie zehn Einer.')}<small>Öffne einen Zehner. Bleibt deine Zahl gleich?</small></div></div>`;}
function renderFree(){return `<section class="card"><div class="exercise-top"><div><div class="exercise-label">PLATZ FÜR DEINE IDEEN</div><h2 class="free-title">Was möchtest du entdecken?</h2></div><div class="pill-toggle" role="group" aria-label="Material wählen"><button class="${freeView==='split'?'active':''}" data-free-view="split" aria-pressed="${freeView==='split'}">Zahlen teilen</button><button class="${freeView==='bank'?'active':''}" data-free-view="bank" aria-pressed="${freeView==='bank'}">Einer & Zehner</button></div></div>${freeView==='split'?renderFreeSplit():renderBank()}</section><div class="hint-bar"><span class="symbol">✧</span><p><strong>Probier auch den Rückweg.</strong><br>${freeView==='split'?'Teile deine Zahl. Schiebe sie wieder zusammen.':'Aus zehn Einern wird ein Zehner. Aus einem Zehner werden zehn Einer.'}</p></div>`;}
function render(){const active=document.activeElement,key=active?.dataset?.action,id=active?.id;const info={bridge:['DIE ZEHNERBRÜCKE','Mach die Zehn voll.','Nimm die fehlenden Steine aus der zweiten Zahl.'],split:['TEILEN & ENTDECKEN','Eine Zahl. Zwei Teile.','Verschiebe einen Teil. Entdecke, was übrig bleibt.'],free:['DEINE FREIE WERKSTATT','Was steckt in deiner Zahl?','Baue, teile und tausche. Hier bestimmst du.']}[mode];$('#eyebrow').textContent=info[0];$('#page-title').textContent=info[1];$('#subtitle').textContent=info[2];document.querySelectorAll('[data-mode]').forEach(b=>{const current=b.dataset.mode===mode;b.classList.toggle('active',current);if(current)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});workspace.innerHTML=mode==='bridge'?renderBridge():mode==='split'?renderSplit():renderFree();if(!document.contains(active)){const next=id?document.getElementById(id):key?workspace.querySelector(`[data-action="${key}"]`):null;if(next&&!next.disabled)next.focus({preventScroll:true});}}
function transfer(ids=selected){if(!ids.length){message='Wähle zuerst einen oder mehrere orange Steine aus.';render();announce(message);return;}const old=mode==='bridge'?bs:ss,next=mode==='bridge'?moveBridge(old,ids):moveSplit(old,ids);if(next===old){const free=mode==='bridge'?10-bs.a-bs.moved.length:ss.take-ss.moved.length;message=`Hier passen noch ${free} ${free===1?'Stein':'Steine'} hinein. Wähle eine kleinere Gruppe.`;render();announce(message);return;}remember();if(mode==='bridge')bs=next;else ss=next;selected=[];message='';hint=false;render();announce(mode==='bridge'?bridgeInstruction():splitInstruction());if(next.phase==='rest')requestAnimationFrame(()=>workspace.querySelector('.answer')?.focus({preventScroll:true}));}
function answer(n,type){message='';if(type==='mental'){if(n!==bs.a+bs.b){message='Versuche es mit einer vollen Zehn. Du kannst die Steine aufdecken.';render();announce(message);return;}memory=false;message='Das Ergebnis passt. Zeige jetzt deinen Weg mit den Steinen.';render();return;}const correct=type==='split-rest'?ss.n-ss.take:type==='rest'?bs.b-bs.moved.length:bs.a+bs.b;if(n!==correct){message=type==='total'?`Du hast eine volle Zehn und noch ${bs.b-bs.moved.length}. Welche Zahl passt dazu?`:'Schau auf die Steine, die auf der Ausgangsmatte geblieben sind. Die leeren Kreise zählen nicht mit.';render();announce(message);return;}remember();if(type==='split-rest'){ss.phase='done';completed.split.add(splitIndex);}else if(type==='rest')bs.phase='total';else{bs.phase='done';completed.bridge.add(bridgeIndex);}render();announce(type==='rest'?bridgeInstruction():'Das passt. Du hast die Teile zusammen gesehen.');requestAnimationFrame(()=>workspace.querySelector(type==='rest'?'.answer':'[data-action="next"]')?.focus({preventScroll:true}));}
const actions={transfer:()=>transfer(),reset,undo:()=>{const old=history.pop();if(!old)return;({bs,ss,bank,freeN,cut,memory}=old);selected=[];message='';render();},next:()=>{if(mode==='bridge')bridgeIndex=(bridgeIndex+1)%BRIDGES.length;else splitIndex=(splitIndex+1)%SPLITS.length;reset();announce('Eine neue Aufgabe wartet.');},hint:()=>{hint=true;if(mode==='bridge')message=bs.phase==='place'?`Zur ${bs.a} fehlen insgesamt ${10-bs.a}. Nimm sie aus der ${bs.b}.`:bs.phase==='rest'?`Die ${bs.moved.length} verschobenen Steine liegen schon in der Zehn. Schau nur auf die Steine, die drüben geblieben sind.`:`Zehn und ${bs.b-bs.moved.length} gehören zusammen.`;else message=`Von ${ss.n} Steinen kommen ${ss.take} nach rechts. Die anderen bleiben links.`;render();announce(message);},reunite:()=>{reset();message=`Alle ${ss.n} Steine sind wieder zusammen. Du kannst sie noch einmal teilen.`;render();},'number-down':()=>{remember();freeN=Math.max(1,freeN-1);cut=Math.min(cut,freeN);message='';render();},'number-up':()=>{remember();freeN=Math.min(20,freeN+1);message='';render();},'swap-parts':()=>{remember();cut=freeN-cut;render();},'join-parts':()=>{remember();cut=freeN;render();},build:()=>{const input=$('#build-number'),n=input.value.trim()===''?NaN:Number(input.value);try{const newBank=fromNumber(n);remember();bank=newBank;message=`Du hast ${n} gebaut. Was passiert beim Tauschen?`;}catch(e){message=e.message;}render();announce(message);},'open-ten':()=>{const next=exchange(bank,'open');if(next===bank)return;remember();bank=next;message=`Ein Zehner wurde zu zehn Einern. Es sind immer noch ${value(bank)}.`;render();announce(message);},'bundle-ten':()=>{const next=exchange(bank,'bundle');if(next===bank)return;remember();bank=next;message=`Zehn Einer wurden zu einem Zehner. Es sind immer noch ${value(bank)}.`;render();announce(message);},mental:()=>{memory=true;message='';render();},reveal:()=>{memory=false;message='';render();}};
document.addEventListener('click',e=>{if(suppressClick){suppressClick=false;return;}const button=e.target.closest('button');if(!button||button.disabled)return;if(button.dataset.mode){setMode(button.dataset.mode);return;}if(button.dataset.freeView){freeView=button.dataset.freeView;history=[];message='';render();return;}if(button.hasAttribute('data-select')){const id=Number(button.dataset.select);selected=selected.includes(id)?selected.filter(x=>x!==id):[...selected,id];message='';render();workspace.querySelector(`[data-select="${id}"]`)?.focus({preventScroll:true});return;}if(button.dataset.answer!==undefined){answer(Number(button.dataset.answer),button.dataset.answerType);return;}if(button.dataset.action)actions[button.dataset.action]?.();});
workspace.addEventListener('click',e=>{if(e.target.closest('button'))return;if(e.target.closest('[data-drop]')&&selected.length)transfer();});
workspace.addEventListener('input',e=>{if(e.target.id==='cut'){cut=Number(e.target.value);const display=$('.free-split-display');display.innerHTML=freeDots();display.setAttribute('aria-label',`${freeN} Steine: ${cut} blau und ${freeN-cut} orange`);$('.split-summary').innerHTML=`${freeN} = <span class="blue-text">${cut}</span> + <span class="orange-text">${freeN-cut}</span>`;e.target.setAttribute('aria-valuetext',`${cut} und ${freeN-cut}`);}});
workspace.addEventListener('keydown',e=>{if(e.target.id==='build-number'&&e.key==='Enter')actions.build();});
workspace.addEventListener('pointerdown',e=>{const b=e.target.closest('[data-select]');if(!b||e.button!==0)return;drag={id:Number(b.dataset.select),x:e.clientX,y:e.clientY,pointer:e.pointerId,active:false,avatar:null};b.setPointerCapture?.(e.pointerId);});
document.addEventListener('pointermove',e=>{if(!drag||drag.pointer!==e.pointerId)return;if(Math.hypot(e.clientX-drag.x,e.clientY-drag.y)>7&&!drag.active){drag.active=true;drag.avatar=document.createElement('div');drag.avatar.className='bead orange drag-avatar';const count=selected.includes(drag.id)?selected.length:1;drag.avatar.textContent=count>1?String(count):'';document.body.append(drag.avatar);}if(drag.active){e.preventDefault();drag.avatar.style.left=e.clientX+'px';drag.avatar.style.top=e.clientY+'px';}},{passive:false});
document.addEventListener('pointerup',e=>{if(!drag||drag.pointer!==e.pointerId)return;const current=drag;drag=null;current.avatar?.remove();if(!current.active)return;suppressClick=true;setTimeout(()=>suppressClick=false,0);const target=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-drop]');if(target?.dataset.drop===mode)transfer(selected.includes(current.id)?selected:[current.id]);else{message='Lege die Steine auf die andere Matte. Oder wähle sie durch Antippen aus.';render();announce(message);}});
document.addEventListener('pointercancel',()=>{drag?.avatar?.remove();drag=null;});
$('#speak').addEventListener('click',()=>{if(!('speechSynthesis'in window)){message='Die Vorlesefunktion ist in diesem Browser nicht verfügbar.';render();announce(message);return;}window.speechSynthesis.cancel();const sentence=mode==='bridge'?`${bs.a} plus ${bs.b}. ${bridgeInstruction()}`:mode==='split'?splitInstruction():freeView==='split'?`Teile die ${freeN} in zwei Teile. Verschiebe dazu die Grenze.`:`Du hast ${value(bank)}. Öffne einen Zehner oder bündele zehn Einer.`;const u=new SpeechSynthesisUtterance(sentence);u.lang='de-DE';u.rate=.86;u.onerror=()=>announce('Das Vorlesen ist gerade nicht verfügbar. Du kannst die Aufgabe auf der Seite lesen.');window.speechSynthesis.speak(u);});
$('#parent-content').innerHTML=`<p>Diese Werkstatt übt einen ganz bestimmten Zusammenhang: <strong>Die fehlenden Steine zur Zehn kommen aus der zweiten Zahl. Der Rest gehört weiterhin dazu.</strong></p><h3>Gemeinsam ausprobieren</h3><ul><li>Beginnt bei „Teilen & entdecken“, wenn das Zerlegen noch unklar ist.</li><li>Fragt bei 8 + 5: „Woher kommen die zwei? Was bleibt von der Fünf?“</li><li>Lasst euer Kind selbst verschieben und erklären. Finger und Material dürfen helfen.</li><li>Nach zwei gelösten Zehnerbrücken lässt sich eine Aufgabe zuerst im Kopf versuchen. Die Steine bleiben jederzeit erreichbar.</li><li>Fünf bis zehn entspannte Minuten sind ein guter erster Versuch. Hört auf, wenn es anstrengend wird.</li></ul><h3>Woran ihr Verständnis erkennt</h3><p>Kann euer Kind den Rest vorhersagen und die Idee bei einer anderen Aufgabe nutzen? Eine richtige Antwort oder schnelles Klicken allein zeigen noch nicht, wie es gerechnet hat.</p><h3>Material und Idee</h3><p>Montessori-inspiriertes Tauschen und Bündeln, ergänzt um Fünferstrukturen und gezieltes Zerlegen. Digitales Material ersetzt das Anfassen echter Steine oder Perlen nicht. Probiert dieselbe Aufgabe auch gemeinsam am Tisch.</p><p><a href="https://montessori-ami.org/questions/introducing-number-rods" target="_blank" rel="noopener noreferrer">AMI: Zahlstangen</a> · <a href="https://mahiko.dzlm.de/zahlraum-bis-20-ueberblick/zahlen-zerlegen/grundlagen" target="_blank" rel="noopener noreferrer">DZLM / Mahiko: Zahlzerlegungen</a></p><h3>Gut zu wissen</h3><p>Kein Konto, keine Rangliste und keine Zeitmessung. Entdeckungen werden nur während dieser geöffneten Sitzung gezählt und nicht dauerhaft gespeichert. Die optionale Vorlesefunktion nutzt die Stimme des Browsers bzw. Betriebssystems; deren Verarbeitung hängt vom Gerät ab.</p>`;
$('#parent-open').addEventListener('click',()=>$('#parent-dialog').showModal());$('#parent-close').addEventListener('click',()=>$('#parent-dialog').close());$('#parent-dialog').addEventListener('click',e=>{if(e.target===$('#parent-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
function readState(){return {mode,...(mode==='bridge'?{a:bs.a,b:bs.b,moved:bs.moved.length,remaining:bs.b-bs.moved.length,phase:bs.phase}:mode==='split'?{number:ss.n,take:ss.take,moved:ss.moved.length,phase:ss.phase}:{view:freeView,...(freeView==='bank'?{...bank,total:value(bank)}:{number:freeN,left:cut,right:freeN-cut})})};}
if(document.modelContext?.registerTool){for(const tool of [{name:'read_math_workspace',title:'Zahlenwerkstatt lesen',description:'Read the current material, counts and learning step without changing them.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>readState()},{name:'open_math_workspace',title:'Werkstatt öffnen',description:'Open the split, bridge or free workspace. Does not solve or complete an exercise.',inputSchema:{type:'object',properties:{mode:{type:'string',enum:['split','bridge','free']}},required:['mode'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||Object.keys(input).some(k=>k!=='mode')||!['split','bridge','free'].includes(input.mode))throw new Error('Invalid mode');setMode(input.mode);return readState();}}]){try{Promise.resolve(document.modelContext.registerTool(tool)).catch(()=>{});}catch{}}}
